    f,s,q=[load(doc[k]) for k in ['native_font_proof','native_stored_proof','native_policy_validation']]
    require(f['complete_native_pages']==9 and f['logical_compiled_input_alignment_cases']==72 and all(f[k] for k in ['all9_single_original_four_row_pages','all9_complete_prose_paragraphs','all_first_internal_final_visible_glyphs_in_order_unique_cells_and_bounds','each216x64_plane_exact_independent_current_font_and_all_canaries','all_original_current_font_renderer_instructions_verified','original_pair_phase_and_guards_bound_without_new_substitutions','zero_source_and_compiled_FI_FA_FO_no_substitutions_added','only_original_static_selectors2_25']),'complete font proof')
