    require(q['positive_paragraph_count']==9 and q['negative_count']==len(q['negative_cases'])==50 and all(c['rejected'] for c in q['negative_cases']) and len(q['row_count_reasons'])==2 and q['all_base_QA_diagnostics_preserved_one_exact_R15_phrasal_verb_classification'],'policy obligations')
    warnings=[(r['id'],r['exact_reviewed_base_warnings'],r['qa_waivers'],r['qa_waiver_reason']) for r in doc['records'] if r['exact_reviewed_base_warnings']]
    require(len(warnings)==1 and warnings[0][0]=='DK4_MES_B227_R0015' and warnings[0][1]==[dict(severity='warning',code='weak-line-ending',message="line 2 ends with weak wrap word 'in,'")] and warnings[0][2]==['weak-line-ending'] and warnings[0][3],'one exact phrasal-verb warning')
    require(sum(bool(r['row_count_reason']) for r in doc['records'])==2,'two exact row reasons')
    names=load(doc['speaker_name_review']);require(all(names[k] for k in ['both_actual_final_English_personal_names_complete','two_contextual_personal_names_retained_no_assets_or_duplicate_credit','quoted_teacher_not_family_naval_rank_orpresent_actor','full207_name_role_alias_andearlier_name_review_open','no_new_name_or_dialogue_credit']),'name consumers andscope')
    for n in names['records']:
        actor=n['actor_ID'];require(n['english']=={2:'Lil Argot',25:'Yifa Sol'}[actor] and [f['Japanese'] for f in n['source_fields'] if f.get('Japanese')]=={2:['リル','アーゴット'],25:['イファ','ソル']}[actor],'exact source personal fields')
