    expected=[(638,678,'00a0ffff37000110'),(646,686,'00a0ffff010d1960'),(654,694,'00a0ffff010e1960')]
    require([(r['source_offset'],r['target_offset'],r['source_hex']) for r in c['three_source_andrelocated_A000_cases']]==expected,'three original effects')
